   freitext_transport_verpackung_de_ist VARCHAR(15)      COLLATE 'en-ci' COMMENT 'Freitextfeld: Transportverpackung, nur für DE gefüllt, bspw. LIN oder KARTON - Feld VERPACKTRANS',
   kontrollnotwendigkeit_vorerntenummer_ist_fg INTEGER     NOT NULL DEFAULT 0 COMMENT 'Flag für QS, sagt aus ob Vorerntenummer kontrolliert wurde - Feld VORERNTE',
   palettenfaktor_ist                  INTEGER     COMMENT 'Pallettenfaktor/Menge in Paletten, bspw. 100 oder 60 - Feld MENGEP',
   vertragsanbau_ist_fg                INTEGER     NOT NULL DEFAULT 0 COMMENT 'Flag das aussagt, ob es Vertragsanbau gibt - Feld CONTRACT_FRAMING',
   nationale_produktion_ist_fg         INTEGER     NOT NULL DEFAULT 0 COMMENT 'Flag das aussagt, ob Produkt einer nationalen Produktion unterliegt - Feld NATIONAL_PROD',
