   kaliber_bis_ist                     INTEGER     COMMENT 'Kaliber, Größe, Gewicht bis, bspw. 1000 - Feld KALBIS',
   freitext_fruchtgehalt_ist           VARCHAR(20)      COLLATE 'en-ci' COMMENT 'Freitextfeld: Zuckergehalt des Artikels - Feld SALES_UNIT',
   dat_empfang                         DATE             COMMENT 'Empfangsdatum - Feld RECEIVE_DATE',
   dat_antwort                         DATE             COMMENT 'Antwortdatum - Feld RESPONSE_DATE',
   zeit_antwort                        TIMESTAMP_LTZ(9) COMMENT 'Antwortzeit - Feld RESPONSE_DATE',
   dat_aenderung                       DATE            DEFAULT 1900-01-01 NOT NULL COMMENT 'Änderungsdatum, Datum an dem der Satz hinzugefügt wurde - Feld AEDAT',
   anz_kolli                           NUMBER(29,3)     COMMENT 'Anzahl Kolli - Feld KOLLI',
   qa_status                           VARCHAR(2)       COLLATE 'en-ci' COMMENT 'QA Status, bspw. A für Konzession, R für Verweigerung, S für Annahme - Feld QA_STATUS',
   anz_kolli_ist                       INTEGER     COMMENT 'Kollianzahl IST- Feld QA_MENGEP',
   charge_vorhanden_ist_fg             INTEGER     NOT NULL DEFAULT 0 COMMENT 'Flag, das aussagt, ob eine Charge vorhanden ist - Feld CHARGE_VORHANDEN',
   lieferant_charge_nr                 VARCHAR(15)      COMMENT 'Lieferantenchargennummer',
   gtin_vorhanden_fg                   INTEGER     COMMENT 'Flag, welche aussagt, ob eine GTIN für den Artikel vorhanden (1) ist oder nicht (0).',
   datzeit_eingang                     TIMESTAMP_LTZ(9) COMMENT 'Eingangszeitstempel der QA-Meldung',
   TD_UPDATE                           TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   TD_INSERT                           TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   CONSTRAINT PK_CHARGE_IST_QA_CHECK PRIMARY KEY (mandant_id, wup_id, nb_id, lagernummer_id, tour_id, lief_beleg_id, gp_id, art_id, charge_id, charge_nr_qa) NOT ENFORCED
)  COMMENT = 'SAP RET INT ZLV_QA_OG_ACT - enthält die O&G Chargenwerte, die an das VZ geliefert werden (IST), z.B. Äpfel in der Größe 75mm - ZOG_CHAR bzw. charge_ist bildet das SOLL ab';
